import { randomBytes } from "node:crypto";
import { existsSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const file = resolve(process.cwd(), ".env.local");
if (existsSync(file)) {
  console.error("An .env.local file already exists. It was not changed. Configure ADMIN_PASSWORD and ADMIN_SESSION_SECRET there if needed.");
  process.exitCode = 1;
} else {
  const contents = [
    "# Local credentials generated by npm run setup:local. Never commit this file.",
    `ADMIN_PASSWORD=${randomBytes(24).toString("base64url")}`,
    `ADMIN_SESSION_SECRET=${randomBytes(48).toString("base64url")}`,
    "NEXT_PUBLIC_SITE_URL=http://localhost:3000",
    "NEXT_TELEMETRY_DISABLED=1",
    "",
  ].join("\n");
  writeFileSync(file, contents, { encoding: "utf8", flag: "wx", mode: 0o600 });
  console.log("Local admin credentials saved to .env.local. Use ADMIN_PASSWORD to sign in at /admin. No credentials were printed.");
}
